# Good 2-digit numbers derived from the previous run
good_2_digit_numbers = {12, 13, 14, 15, 16, 17, 18, 19, 21, 24, 25, 26, 28, 31, 32, 35, 36, 39, 41, 42, 45, 48, 51, 52, 61, 62, 63, 64, 65, 71, 72, 75, 81, 82, 84, 85, 91, 92, 93, 95, 96}

def is_good_3_digit(a, b, c, good_2_digits):
    # m = 100*a + 10*b + c. Digits a, b, c must be distinct and non-zero.
    if a == b or a == c or b == c or a == 0 or b == 0 or c == 0:
        return False

    m = 100 * a + 10 * b + c

    # Case 1: Remove 'a'. Remaining m' = 10*b + c
    m_prime = 10 * b + c
    is_case1_good = m_prime in good_2_digits and m % m_prime == 0

    # Case 2: Remove 'b'. Remaining m'' = 10*a + c
    m_double_prime = 10 * a + c
    is_case2_good = m_double_prime in good_2_digits and m % m_double_prime == 0

    # Case 3: Remove 'c'. Remaining m''' = 10*a + b
    m_triple_prime = 10 * a + b
    is_case3_good = m_triple_prime in good_2_digits and m % m_triple_prime == 0

    return is_case1_good or is_case2_good or is_case3_good

good_3_digit_numbers = []
digits = [1, 2, 3, 4, 5, 6, 7, 8, 9]

# Iterate over all distinct triplets (a, b, c)
for a in digits:
    for b in digits:
        if a == b:
            continue
        for c in digits:
            if c == a or c == b:
                continue

            if is_good_3_digit(a, b, c, good_2_digit_numbers):
                good_3_digit_numbers.append(100 * a + 10 * b + c)

print("Good 3-digit numbers found:", sorted(good_3_digit_numbers))

# Find the largest good 3-digit number
if good_3_digit_numbers:
    largest_3_digit = max(good_3_digit_numbers)
    print(f"Largest good 3-digit number: {largest_3_digit}")
else:
    print("No good 3-digit numbers found.")
